// Content with portions generated by generative AI platform
package org.eclipse.kura.core.internal.linux.executor;

import static java.nio.charset.StandardCharsets.UTF_8;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.doAnswer;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.io.UncheckedIOException;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;

import org.apache.commons.exec.CommandLine;
import org.apache.commons.exec.DefaultExecutor;
import org.apache.commons.exec.ExecuteException;
import org.apache.commons.exec.ExecuteResultHandler;
import org.apache.commons.exec.Executor;
import org.eclipse.kura.executor.Command;
import org.eclipse.kura.executor.CommandStatus;
import org.junit.Test;

public class ExecutorUtilFailureReportingTest {

    private static final int START_FAILURE_EXIT_VALUE = 1;
    private static final String START_FAILURE = "Failed to start command: ";
    private static final String MISSING_EXECUTABLE = "/nonexistent/kura-missing-command";
    private static final String CALL_SITE_FAILURE_MESSAGE = "Working directory does not exist";
    private static final String WRITE_FAILURE_MESSAGE = "write failed";
    private static final String READ_FAILURE_MESSAGE = "read failed";
    private static final String LARGE_OUTPUT_BYTES = Integer.toString(1 << 20);
    private static final int COMMAND_TIMEOUT_SECONDS = 10;
    private static final String PREVIOUS_STDERR = "previous stderr\n";

    private final DefaultExecutor executor = mock(DefaultExecutor.class);
    private final AtomicInteger callbackInvocations = new AtomicInteger();
    private final CountDownLatch callbackLatch = new CountDownLatch(1);
    private ExecutorUtil executorUtil;
    private Command command;
    private ByteArrayOutputStream callerErrorStream;
    private CommandStatus status;

    @Test
    public void commandNotFoundSyncReportsCause() {
        givenRealExecutor();
        givenCommand(MISSING_EXECUTABLE);

        whenExecutedSync();

        thenExitCodeIs(START_FAILURE_EXIT_VALUE);
        thenErrorStreamContains(START_FAILURE);
        thenErrorStreamContains(MISSING_EXECUTABLE);
    }

    @Test
    public void commandNotFoundAsyncCallsCallbackOnceWithCause() {
        givenRealExecutor();
        givenCommand(MISSING_EXECUTABLE);

        whenExecutedAsync();

        thenCallbackIsCalledOnce();
        thenExitCodeIs(START_FAILURE_EXIT_VALUE);
        thenErrorStreamContains(START_FAILURE);
        thenErrorStreamContains(MISSING_EXECUTABLE);
    }

    @Test
    public void asyncStartFailureAtCallSiteCallsCallbackWithCause() {
        givenMockedExecutor();
        givenAsyncCallSiteThrows(false);
        givenCommand("ls");

        whenExecutedAsync();

        thenCallbackIsCalledOnce();
        thenExitCodeIs(START_FAILURE_EXIT_VALUE);
        thenErrorStreamContains(START_FAILURE + CALL_SITE_FAILURE_MESSAGE);
    }

    @Test
    public void asyncStartFailureReportedTwiceCallsCallbackOnce() {
        givenMockedExecutor();
        givenAsyncCallSiteThrows(true);
        givenCommand("ls");

        whenExecutedAsync();

        thenCallbackIsCalledOnce();
        thenExitCodeIs(START_FAILURE_EXIT_VALUE);
    }

    @Test
    public void nonZeroExitLeavesCallerErrorStreamUntouched() {
        givenMockedExecutor();
        givenSyncExitCode(127);
        givenCommand("ls");
        givenCallerErrorStream(PREVIOUS_STDERR);

        whenExecutedSync();

        thenExitCodeIs(127);
        thenCallerErrorStreamIs(PREVIOUS_STDERR);
    }

    @Test
    public void failingOutputStreamMarksOutputIncomplete() {
        givenRealExecutor();
        givenCommand("echo", "hello");
        givenFailingOutputStream();

        whenExecutedSync();

        thenOutputIncompleteIs(true);
        thenErrorStreamContains("Output may be incomplete: " + WRITE_FAILURE_MESSAGE);
    }

    @Test
    public void failingOutputStreamDoesNotBlockTheProcess() {
        givenRealExecutor();
        givenCommand("head", "-c", LARGE_OUTPUT_BYTES, "/dev/zero");
        givenTimeout(COMMAND_TIMEOUT_SECONDS);
        givenFailingOutputStream();

        whenExecutedSync();

        thenTimedOutIs(false);
        thenExitCodeIs(0);
        thenOutputIncompleteIs(true);
    }

    @Test
    public void unreadableInputIsReported() {
        givenRealExecutor();
        givenCommand("cat");
        givenUnreadableInput();

        whenExecutedSync();

        thenOutputIncompleteIs(false);
        thenErrorStreamContains("Failed to read the input for the process: " + READ_FAILURE_MESSAGE);
    }

    @Test
    public void successfulCommandAddsNothingToTheErrorStream() {
        givenRealExecutor();
        givenCommand("echo", "hello");
        givenCallerErrorStream("");

        whenExecutedSync();

        thenExitCodeIs(0);
        thenOutputIncompleteIs(false);
        thenCallerErrorStreamIs("");
    }

    private void givenRealExecutor() {
        this.executorUtil = new ExecutorUtil();
    }

    private void givenMockedExecutor() {
        this.executorUtil = new ExecutorUtil() {

            @Override
            protected Executor getExecutor() {
                return ExecutorUtilFailureReportingTest.this.executor;
            }
        };
    }

    private void givenAsyncCallSiteThrows(boolean handlerAlreadyNotified) {
        IOException failure = new IOException(CALL_SITE_FAILURE_MESSAGE);
        ExecuteException wrapped = new ExecuteException("Execution failed", Executor.INVALID_EXITVALUE, failure);
        try {
            doAnswer(invocation -> {
                if (handlerAlreadyNotified) {
                    invocation.<ExecuteResultHandler> getArgument(1).onProcessFailed(wrapped);
                }
                throw failure;
            }).when(this.executor).execute(any(CommandLine.class), any(ExecuteResultHandler.class));
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    private void givenSyncExitCode(int exitCode) {
        try {
            when(this.executor.execute(any(CommandLine.class)))
                    .thenThrow(new ExecuteException("Process exited with an error: " + exitCode, exitCode));
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    private void givenCommand(String... commandLine) {
        this.command = new Command(commandLine);
    }

    private void givenCallerErrorStream(String content) {
        this.callerErrorStream = new ByteArrayOutputStream();
        byte[] bytes = content.getBytes(UTF_8);
        this.callerErrorStream.write(bytes, 0, bytes.length);
        this.command.setErrorStream(this.callerErrorStream);
    }

    private void givenFailingOutputStream() {
        this.command.setOutputStream(new OutputStream() {

            @Override
            public void write(int b) throws IOException {
                throw new IOException(WRITE_FAILURE_MESSAGE);
            }
        });
    }

    private void givenUnreadableInput() {
        this.command.setInputStream(new InputStream() {

            @Override
            public int read() throws IOException {
                throw new IOException(READ_FAILURE_MESSAGE);
            }
        });
    }

    private void givenTimeout(int seconds) {
        this.command.setTimeout(seconds);
    }

    private void whenExecutedSync() {
        this.status = this.executorUtil.executePrivileged(this.command);
    }

    private void whenExecutedAsync() {
        this.executorUtil.executePrivileged(this.command, result -> {
            this.status = result;
            this.callbackInvocations.incrementAndGet();
            this.callbackLatch.countDown();
        });
    }

    private void thenCallbackIsCalledOnce() {
        try {
            assertTrue("The callback was not called", this.callbackLatch.await(30, TimeUnit.SECONDS));
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new IllegalStateException(e);
        }
        assertEquals(1, this.callbackInvocations.get());
    }

    private void thenExitCodeIs(int expected) {
        assertEquals(expected, this.status.getExitStatus().getExitCode());
    }

    private void thenErrorStreamContains(String expected) {
        String errorOutput = this.status.getErrorStream().toString();
        assertTrue("'" + errorOutput + "' does not contain '" + expected + "'", errorOutput.contains(expected));
    }

    private void thenTimedOutIs(boolean expected) {
        assertEquals(expected, this.status.isTimedout());
    }

    private void thenOutputIncompleteIs(boolean expected) {
        assertEquals(expected, this.status.isOutputIncomplete());
    }

    private void thenCallerErrorStreamIs(String expected) {
        assertSame(this.callerErrorStream, this.status.getErrorStream());
        assertEquals(expected, new String(this.callerErrorStream.toByteArray(), UTF_8));
    }
}
